@app.post("/payments")
def pay(body: PaymentIn, idempotency_key: str = Header(...)):
    if idempotency_key in store:
        return store[idempotency_key]
    result = charge(body)
    store[idempotency_key] = result
    return result

@BatchMapping
public Map<Book, Author> author(List<Book> books) {
  Map<Long, Author> byId = authorRepo.findAllById(books.stream().map(Book::authorId).toList())
      .stream().collect(Collectors.toMap(Author::id, a -> a));
  return books.stream().collect(Collectors.toMap(b -> b, b -> byId.get(b.authorId())));
}

@strawberry.type
class Book:
    title: str

@strawberry.type
class Query:
    @strawberry.field
    def books(self) -> list[Book]:
        return [Book(title="Dune")]

schema = strawberry.Schema(query=Query)
